CREATE TABLE public.platform_release_flags(name text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false); GRANT SELECT ON public.platform_release_flags TO authenticated; GRANT ALL ON public.platform_release_flags TO service_role; ALTER TABLE public.platform_release_flags ENABLE ROW LEVEL SECURITY; CREATE POLICY release_flags_admin_read ON public.platform_release_flags FOR SELECT TO authenticated USING(public.is_platform_admin());
CREATE OR REPLACE FUNCTION public.enforce_organization_onboarding_gate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.platform_release_flags WHERE name='organization_onboarding' AND enabled) AND NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Organization onboarding awaits validation'; END IF; IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.slug IS DISTINCT FROM OLD.slug) THEN RAISE EXCEPTION 'Organization identity is immutable'; END IF; RETURN NEW; END $$;